const SOCKET_URL = 'ws://localhost:8080'
const CLIENT_ID = 'frontend'
const TARGET_ID = 'backend'

let socket = null
let counter = 0

const pending = new Map()
const subscribers = new Set()

function initConnection() {
  if (typeof window === 'undefined' || !window.WebSocket) return

  try {
    socket = new WebSocket(SOCKET_URL)

    socket.addEventListener('open', () => {
      console.log(`io: connected → ${SOCKET_URL}`)
    })

    socket.addEventListener('close', () => {
      console.log('io: disconnected, retrying...')
      setTimeout(initConnection, 2000)
    })

    socket.addEventListener('error', (e) => {
      console.error('io: socket error', e)
    })

    socket.addEventListener('message', handleIncoming)
  } catch (e) {
    console.error('io: init failed', e)
  }
}

function handleIncoming(event) {
  let message
  try {
    message = JSON.parse(event.data)
  } catch {
    return
  }

  const id = message.head ? message.head.join(',') : null

  if (id && pending.has(id)) {
    const cb = pending.get(id)
    pending.delete(id)
    if (typeof cb === 'function') cb(message)
  }

  subscribers.forEach(fn => {
    if (typeof fn === 'function') fn(message)
  })
}

initConnection()

function dispatch(type, payload, callback) {
  if (!socket || socket.readyState !== WebSocket.OPEN) {
    console.warn(`io: cannot send "${type}", socket not ready`)
    if (callback) callback({ error: 'not ready' })
    return
  }

  const id = counter++
  const header = [CLIENT_ID, TARGET_ID, id]

  if (callback) {
    const key = ['backend', CLIENT_ID, id].join(',')
    pending.set(key, callback)
  }

  socket.send(JSON.stringify({
    head: header,
    type,
    data: payload
  }))
}

function subscribe(fn) {
  subscribers.add(fn)
  return () => subscribers.delete(fn)
}

module.exports = {
  send: dispatch,
  listen: subscribe,
  get status() {
    return socket ? socket.readyState : null
  },
  OPEN: (typeof window !== 'undefined' && window.WebSocket)
    ? window.WebSocket.OPEN
    : 1
}

// ===== fallback =====
function fallback_module() {
  return { api: createInstance }

  function createInstance(config = {}) {
    const base = config.value || {}

    return {
      drive: {
        'data/': {
          'opts.json': {
            raw: config || {}
          }
        }
      },
      _: {},
      value: base
    }
  }
}